{
  "name": "opencode-roadmap-plugin",
  "version": "1.2.0",
  "description": "Generate product roadmaps and improvement ideas in opencode. /roadmap and /ideation slash commands print full output in chat (not just JSON files) so the data is in conversation context for follow-up questions.",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "agents",
    "commands",
    "opencode.json.example",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "roadmap",
    "product-roadmap",
    "ai-agents",
    "minimax",
    "claude",
    "ai-tools"
  ],
  "author": "islamahmedas12-ux",
  "license": "AGPL-3.0",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/islamahmedas12-ux/opencode-roadmap-plugin.git"
  },
  "bugs": {
    "url": "https://github.com/islamahmedas12-ux/opencode-roadmap-plugin/issues"
  },
  "homepage": "https://github.com/islamahmedas12-ux/opencode-roadmap-plugin#readme",
  "engines": {
    "node": ">=20.0.0"
  }
}
